#include "ManualProcedureGraphFixture.hpp"
#include <functional>
#include <iostream>
using namespace fathom;using namespace tasks::manual_procedure_graph;
namespace X=tests::manual_procedure_fixture;using V=json::Value;using O=V::Object;
namespace {
std::size_t assertions{},refusals{},gestures{},paths{};std::string checkpoint;
void check(bool b,const char* why){++assertions;if(!b)throw std::runtime_error(why);}
const V& f(const V& v,const char* n){const auto* p=v.find(n);check(p!=nullptr,"FIELD");return *p;}
std::string state(const ManualProcedureGraph& t){return f(t.learnerView(),"state").string();}
void act(ManualProcedureGraph& t,const std::string& action,const V& payload){const auto token=t.capture(action);check(t.current(token),"CURRENT");t.apply(token,payload);check(!t.current(token),"STALE");++gestures;const auto instructions=t.learnerInstructions();check(f(instructions,"text").isArray()&&f(instructions,"actual_performance_verified")==V(false),"PROJECTION");}
void advance(ManualProcedureGraph& t){act(t,f(t.learnerActions().array().front(),"action").string(),X::positiveFor(t));}
void to(ManualProcedureGraph& t,const char* target){for(int i=0;i<60;++i){const auto v=t.learnerView();if(state(t)=="active"&&f(v,"node")==V(target))return;check(state(t)!="needs_retry","PATH_DIAGNOSED");advance(t);}throw std::runtime_error("PATH_LIMIT");}
void refuse(ManualProcedureGraph& t,const std::function<void()>& call){const auto view=t.learnerView(),history=V(t.history());bool rejected=false;try{call();}catch(const tasks::recipes::Error&){rejected=true;}check(rejected,"REFUSAL_REQUIRED");check(view==t.learnerView()&&history==V(t.history()),"REFUSAL_MUTATED");++refusals;}
void finishFsharp(ManualProcedureGraph& t){act(t,"choose",O{{"reported_tonic","F#"}});check(f(t.learnerView(),"node")==V("criterion_001"),"F_SHARP_ROUTE");advance(t);check(state(t)=="completed","F_SHARP_CONDITIONAL_REPAIR_FORCED");for(const auto& entry:t.history()){check(f(entry,"node")!=V("criterion_002")&&f(entry,"node")!=V("criterion_003"),"REMOVED_DECLARATION_IN_HISTORY");check(f(entry,"observed_performance")==V(false)&&f(entry,"grants_credit")==V(false),"CREDIT");}++paths;}
}
int main(){try{
const auto& d=definition("proposed-printed-l040-module-c-four-bar-phrases-minor-center-check");const auto& nodes=f(f(d.retainedProgram(),"graph"),"nodes");check(!nodes.find("criterion_002")&&!nodes.find("criterion_003"),"CONDITIONAL_NODES_RETAINED");check(d.contractSha256()=="ed1d340be6dc6902147c40044d97c8850dc137cf767226e0e6e1110bbf15db06","EXACT_PROGRAM");
checkpoint="F# direct";ManualProcedureGraph direct(d);advance(direct);to(direct,"tonic_choice");finishFsharp(direct);for(const auto& entry:direct.history())check(f(entry,"node")!=V("tonic_repair"),"F_SHARP_REPAIR_CLAIMED");
checkpoint="A prescribed repair";ManualProcedureGraph repair(d);advance(repair);to(repair,"tonic_choice");const auto old=repair.capture("choose");act(repair,"choose",O{{"reported_tonic","A"}});check(f(repair.learnerView(),"node")==V("tonic_repair"),"A_REPAIR_MISSING");refuse(repair,[&]{repair.apply(old,O{{"reported_tonic","F#"}});});refuse(repair,[&]{act(repair,"choose",O{{"reported_tonic","F#"}});});advance(repair);check(state(repair)=="await_release"&&f(repair.learnerView(),"needs_manual_release")==V(true),"REPAIR_RELEASE_MISSING");refuse(repair,[&]{repair.apply(repair.capture("release"),O{{"learner_released",false},{"external_source_stopped",true}});});advance(repair);check(f(repair.learnerView(),"node")==V("tonic_choice"),"REPAIR_DID_NOT_RETURN");finishFsharp(repair);
for(const auto* tonic:{"other","unknown"}){checkpoint=tonic;ManualProcedureGraph t(d);advance(t);to(t,"tonic_choice");act(t,"choose",O{{"reported_tonic",tonic}});check(f(t.learnerView(),"node")==V("unresolved_tonic"),"UNKNOWN_REPAIR_INVENTED");auto p=X::positiveFor(t);p.object()["reported_outcome"]="reported_met";refuse(t,[&]{t.apply(t.capture("submit"),p);});p.object()["reported_outcome"]="unknown";act(t,"submit",p);check(state(t)=="needs_retry","UNKNOWN_COMPLETED");advance(t);check(state(t)=="await_release","UNKNOWN_RETRY_EXIT_RELEASE");advance(t);to(t,"repair_choice");advance(t);if(state(t)=="await_release")advance(t);to(t,"tonic_choice");finishFsharp(t);}
for(V outcome:{V(false),V(nullptr)}){checkpoint="A repair negative/unknown";ManualProcedureGraph t(d);advance(t);to(t,"tonic_choice");act(t,"choose",O{{"reported_tonic","A"}});auto p=X::positiveFor(t);p.object()["density_reduced"]=outcome;act(t,"submit",p);check(state(t)=="await_release","FAILED_PHYSICAL_REPAIR_RELEASE");advance(t);check(state(t)=="needs_retry","FAILED_REPAIR_COMPLETED");++paths;}
std::cout<<"{\"outcome\":\"PASS\",\"affected_source_keys\":1,\"paths\":"<<paths<<",\"gestures\":"<<gestures<<",\"assertions\":"<<assertions<<",\"refusals\":"<<refusals<<",\"synthetic_manual_reports\":true,\"actual_performance\":false,\"credit\":false}\n";return 0;
}catch(const std::exception& e){std::cerr<<checkpoint<<": "<<e.what()<<"\n";return 1;}}
